import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../../supabaseClient';
import { useAuth } from '../../context/AuthContext';
import { Send, Upload, CheckCircle, AlertCircle, X, Clock } from 'lucide-react';

const SOFTWARE_OPTIONS = [
  'SketchUp',
  'V-Ray',
  '3ds Max',
  'Corona Renderer',
  'Unreal Engine',
  'Blender',
  'Lumion',
  'Twinmotion',
  'Enscape',
  'Other'
];

const ARCHITECTURE_STYLES = [
  'Contemporary',
  'Classic',
  'Modern',
  'Minimalist',
  'Industrial',
  'Rustic',
  'Eclectic',
  'Art Deco'
];

const PROJECT_TYPES = [
  'Facade',
  'Interiors',
  'Landscaping',
  'Urban',
  'Commercial',
  'Residential',
  'Industrial'
];

function ArtistApplicationForm() {
  const { user, profile, refreshProfile } = useAuth();
  const navigate = useNavigate();
  const [submitted, setSubmitted] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [uploadingFiles, setUploadingFiles] = useState(false);
  const [existingApplication, setExistingApplication] = useState(null);
  const [loading, setLoading] = useState(true);

  const [formData, setFormData] = useState({
    portfolio_urls: ['', '', ''],
    portfolio_files: [],
    software: [],
    other_software: '',
    years_experience: 0,
    architecture_style: [],
    favorite_project_types: []
  });

  useEffect(() => {
    checkExistingApplication();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user]);

  const checkExistingApplication = async () => {
    if (!user) return;

    try {
      const { data, error } = await supabase
        .from('artist_submissions')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false })
        .limit(1);

      if (error) throw error;

      if (data && data.length > 0) {
        setExistingApplication(data[0]);

        // If application is still pending, show it
        if (data[0].status === 'pending') {
          setSubmitted(true);
        } else if (data[0].status === 'approved') {
          // If approved, redirect to dashboard
          navigate('/dashboard');
        } else if (data[0].status === 'rejected') {
          // Allow reapplication if rejected
          setFormData({
            portfolio_urls: data[0].portfolio_urls || ['', '', ''],
            portfolio_files: data[0].portfolio_files || [],
            software: data[0].software || [],
            other_software: data[0].other_software || '',
            years_experience: data[0].years_experience || 0,
            architecture_style: data[0].architecture_style || [],
            favorite_project_types: data[0].favorite_project_types || []
          });
        }
      }
    } catch (err) {
      console.error('Error checking existing application:', err);
    } finally {
      setLoading(false);
    }
  };

  const toggleArrayItem = (array, item) => {
    if (array.includes(item)) {
      return array.filter(i => i !== item);
    }
    return [...array, item];
  };

  const handlePortfolioUrlChange = (index, value) => {
    const newUrls = [...formData.portfolio_urls];
    newUrls[index] = value;
    setFormData({ ...formData, portfolio_urls: newUrls });
  };

  const handleFileUpload = async (e) => {
    const files = Array.from(e.target.files);

    if (files.length + formData.portfolio_files.length > 10) {
      setError('Maximum of 10 portfolio files');
      return;
    }

    // Validate file types and sizes
    const validFiles = files.filter(file => {
      if (!file.type.startsWith('image/')) {
        setError(`${file.name} is not a valid image`);
        return false;
      }
      if (file.size > 10 * 1024 * 1024) {
        setError(`${file.name} exceeds 10MB`);
        return false;
      }
      return true;
    });

    setUploadingFiles(true);
    setError('');

    try {
      const uploadedUrls = [];

      for (const file of validFiles) {
        const fileExt = file.name.split('.').pop();
        const fileName = `applications/${user.id}/${Date.now()}_${Math.random().toString(36).substring(7)}.${fileExt}`;

        const { error: uploadError } = await supabase.storage
          .from('portfolio-submissions')
          .upload(fileName, file);

        if (uploadError) throw uploadError;

        const { data: urlData } = supabase.storage
          .from('portfolio-submissions')
          .getPublicUrl(fileName);

        uploadedUrls.push(urlData.publicUrl);
      }

      setFormData({
        ...formData,
        portfolio_files: [...formData.portfolio_files, ...uploadedUrls]
      });
    } catch (err) {
      console.error('Error uploading files:', err);
      setError('Error uploading files. Please try again.');
    } finally {
      setUploadingFiles(false);
    }
  };

  const removePortfolioFile = (index) => {
    const newFiles = formData.portfolio_files.filter((_, i) => i !== index);
    setFormData({ ...formData, portfolio_files: newFiles });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    setError('');

    // Validation
    if (formData.software.length === 0) {
      setError('Please select at least one software');
      setSubmitting(false);
      return;
    }

    if (formData.architecture_style.length === 0) {
      setError('Please select at least one architecture style');
      setSubmitting(false);
      return;
    }

    if (formData.favorite_project_types.length === 0) {
      setError('Please select at least one favorite project type');
      setSubmitting(false);
      return;
    }

    // At least one portfolio URL or file
    const hasPortfolioUrls = formData.portfolio_urls.some(url => url.trim() !== '');
    const hasPortfolioFiles = formData.portfolio_files.length > 0;

    if (!hasPortfolioUrls && !hasPortfolioFiles) {
      setError('Please provide at least one portfolio link or upload images');
      setSubmitting(false);
      return;
    }

    try {
      // Clean up portfolio URLs (remove empty strings)
      const cleanedUrls = formData.portfolio_urls.filter(url => url.trim() !== '');

      const { error: submitError } = await supabase
        .from('artist_submissions')
        .insert({
          user_id: user.id,
          email: user.email,
          full_name: profile?.full_name || 'User',
          phone: profile?.phone || '',
          portfolio_urls: cleanedUrls,
          portfolio_files: formData.portfolio_files,
          software: formData.software,
          other_software: formData.other_software,
          years_experience: formData.years_experience,
          architecture_style: formData.architecture_style,
          favorite_project_types: formData.favorite_project_types,
          status: 'pending'
        });

      if (submitError) throw submitError;

      setSubmitted(true);
      // Refresh profile to get latest data
      if (refreshProfile) {
        await refreshProfile();
      }
    } catch (err) {
      console.error('Error submitting application:', err);
      setError('Error submitting application. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="loading-screen">
        <div className="logo-icon">3D</div>
        <p>Loading...</p>
      </div>
    );
  }

  if (submitted) {
    return (
      <div className="application-success">
        <div className="success-content">
          <CheckCircle size={64} className="success-icon" />
          <h1>Application Submitted Successfully!</h1>
          <p>
            Thank you for applying as a 3D artist at 3dMatch.
            Our team will review your application within 2 business days.
          </p>
          <p>
            You will receive an email notification once your application has been reviewed.
          </p>
          {existingApplication?.status === 'pending' && (
            <div className="pending-notice">
              <Clock size={20} />
              <span>Your application is under review</span>
            </div>
          )}
          <button
            className="btn-primary"
            onClick={() => navigate('/dashboard')}
          >
            Back to Dashboard
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="content-section">
      <div className="application-header">
        <h1>Complete Your 3D Artist Application</h1>
        <p className="subtitle">
          Fill in the information below to complete your application.
          Our team will review it and you will receive a notification with the result.
        </p>
      </div>

      {existingApplication?.status === 'rejected' && (
        <div className="alert alert-warning">
          <AlertCircle size={20} />
          <div>
            <strong>Previous Application Rejected</strong>
            <p>You can resubmit your application with updated information.</p>
            {existingApplication.review_notes && (
              <p><em>Feedback: {existingApplication.review_notes}</em></p>
            )}
          </div>
        </div>
      )}

      {error && (
        <div className="alert alert-error">
          <AlertCircle size={20} />
          <span>{error}</span>
        </div>
      )}

      <form onSubmit={handleSubmit} className="artist-application-form">
        {/* Software */}
        <div className="form-group">
          <label className="form-label required">
            Software you master
          </label>
          <div className="checkbox-grid">
            {SOFTWARE_OPTIONS.map(software => (
              <label key={software} className="checkbox-label">
                <input
                  type="checkbox"
                  checked={formData.software.includes(software)}
                  onChange={() => setFormData({
                    ...formData,
                    software: toggleArrayItem(formData.software, software)
                  })}
                />
                <span>{software}</span>
              </label>
            ))}
          </div>
        </div>

        {formData.software.includes('Other') && (
          <div className="form-group">
            <label className="form-label">Other software</label>
            <input
              type="text"
              className="form-input"
              value={formData.other_software}
              onChange={(e) => setFormData({ ...formData, other_software: e.target.value })}
              placeholder="List other software you use"
            />
          </div>
        )}

        {/* Years of Experience */}
        <div className="form-group">
          <label className="form-label required">
            Years of experience with 3D rendering
          </label>
          <input
            type="number"
            className="form-input"
            min="0"
            max="50"
            value={formData.years_experience}
            onChange={(e) => setFormData({ ...formData, years_experience: parseInt(e.target.value) || 0 })}
            required
          />
        </div>

        {/* Architecture Styles */}
        <div className="form-group">
          <label className="form-label required">
            Architecture styles you work with
          </label>
          <div className="checkbox-grid">
            {ARCHITECTURE_STYLES.map(style => (
              <label key={style} className="checkbox-label">
                <input
                  type="checkbox"
                  checked={formData.architecture_style.includes(style)}
                  onChange={() => setFormData({
                    ...formData,
                    architecture_style: toggleArrayItem(formData.architecture_style, style)
                  })}
                />
                <span>{style}</span>
              </label>
            ))}
          </div>
        </div>

        {/* Project Types */}
        <div className="form-group">
          <label className="form-label required">
            Favorite project types
          </label>
          <div className="checkbox-grid">
            {PROJECT_TYPES.map(type => (
              <label key={type} className="checkbox-label">
                <input
                  type="checkbox"
                  checked={formData.favorite_project_types.includes(type)}
                  onChange={() => setFormData({
                    ...formData,
                    favorite_project_types: toggleArrayItem(formData.favorite_project_types, type)
                  })}
                />
                <span>{type}</span>
              </label>
            ))}
          </div>
        </div>

        {/* Portfolio URLs */}
        <div className="form-group">
          <label className="form-label">
            Portfolio Links (Optional)
          </label>
          <p className="form-hint">
            Add links to your portfolio (Behance, ArtStation, personal website, etc.)
          </p>
          {formData.portfolio_urls.map((url, index) => (
            <input
              key={index}
              type="url"
              className="form-input"
              value={url}
              onChange={(e) => handlePortfolioUrlChange(index, e.target.value)}
              placeholder={`Link ${index + 1}`}
              style={{ marginBottom: '0.5rem' }}
            />
          ))}
        </div>

        {/* Portfolio Files */}
        <div className="form-group">
          <label className="form-label">
            Portfolio Images
          </label>
          <p className="form-hint">
            Upload up to 10 images of your work (maximum 10MB each)
          </p>

          <div className="file-upload-area">
            <input
              type="file"
              id="portfolio-files"
              multiple
              accept="image/*"
              onChange={handleFileUpload}
              disabled={uploadingFiles || formData.portfolio_files.length >= 10}
              style={{ display: 'none' }}
            />
            <label htmlFor="portfolio-files" className="file-upload-label">
              <Upload size={24} />
              <span>
                {uploadingFiles ? 'Uploading...' : 'Click to upload images'}
              </span>
            </label>
          </div>

          {formData.portfolio_files.length > 0 && (
            <div className="uploaded-files">
              {formData.portfolio_files.map((url, index) => (
                <div key={index} className="uploaded-file">
                  <img src={url} alt={`Portfolio ${index + 1}`} />
                  <button
                    type="button"
                    onClick={() => removePortfolioFile(index)}
                    className="remove-file-btn"
                  >
                    <X size={16} />
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="form-actions">
          <button
            type="submit"
            className="btn-primary btn-large"
            disabled={submitting}
          >
            {submitting ? (
              <>Submitting application...</>
            ) : (
              <>
                <Send size={20} />
                Submit Application
              </>
            )}
          </button>
        </div>
      </form>
    </div>
  );
}

export default ArtistApplicationForm;
